// P0.3 — resolve the runtime client scope FIRST. The supervised webhook POST
// body arrives under $json.body in n8n; fall back to direct fields. Emits both
// clientId and clientCode (empty string when not supplied); the downstream
// 'Resolve client' node fills the missing one from the clients table.
const src = ($json && $json.body && typeof $json.body === 'object') ? $json.body : $json;
const clientId = (src && src.clientId) ? String(src.clientId) : '';
const clientCode = (src && src.clientCode) ? String(src.clientCode) : '';
return { json: { clientId: clientId, clientCode: clientCode } };

// P0.13 — Build the intent-generation prompt from the entity + client context
// loaded at runtime. NO industry/business-model is hard-coded: the prompt is
// grounded in the entity's real type and the client's verified claims / region
// / target markets. If context is missing the prompt instructs the model not
// to assume any industry or business model.
const ctx = $node['Load intent context'].json || {};
const entity = ctx.canonical_name || '';
const type = ctx.entity_type || '';
const region = ctx.primary_region || '';
const language = ctx.primary_language || '';
const markets = ctx.target_markets || '';
const claims = ctx.verified_claims || '';
const contextBlock =
  'entity=' + entity + ' (' + type + ')\n' +
  'primary_region=' + region + '\n' +
  'primary_language=' + language + '\n' +
  'target_markets=' + markets + '\n' +
  'verified_claims: ' + (claims || '(none)') + '\n';
const prompt =
  'You are performing GEO discovery for this entity.\n' +
  'Use ONLY the supplied verified context. Do not assume an industry or ' +
  'business model not present in the context.\n\n' +
  'VERIFIED CONTEXT:\n' + contextBlock +
  '\nReturn STRICT JSON only, shape:\n' +
  '{"intents":[{"entity_name":"' + entity + '","intent_type","label","description",' +
  '"commercial","relevance","opportunity",' +
  '"queries":[{"query_text","language":"' + (language || 'zh-CN') + '","region":"' + (region || 'CN') + '","priority"}]}]}\n' +
  'intent_type one of: PRODUCT, PURCHASE, COMPARE, QUESTION, SCENARIO, REGION, ' +
  'TRUST, BRAND, AFTER_SALES. commercial/relevance/opportunity are 0-100 numbers; ' +
  'priority 0-100. Each intent carries 2-5 realistic queries grounded in the verified context.\n\nJSON: ';
return { json: { prompt: prompt } };

// Parse the Ollama JSON response into intent candidates. A non-JSON / empty
// reply yields no items (fail closed). Emits ONE item per valid intent so the
// downstream DB register node runs once per intent. Malformed intents (missing
// intent_type) are skipped.
const scope = $node['Resolve client'].json;
const clientCode = scope.clientCode;
const raw = $json.response || '';
let data = {};
if (typeof raw === 'string') { try { data = JSON.parse(raw); } catch (e) { data = {}; } }
else if (raw && typeof raw === 'object') data = raw;
const intents = Array.isArray(data.intents) ? data.intents : [];
const out = [];
for (const it of intents) {
  if (!it || typeof it !== 'object') continue;
  if (!it.intent_type) continue;
  out.push({
    clientCode: clientCode,
    entityName: it.entity_name,
    intentType: it.intent_type,
    label: it.label,
    description: it.description,
    commercial: it.commercial,
    relevance: it.relevance,
    opportunity: it.opportunity,
    queries: JSON.stringify(it.queries || [])
  });
}
return out;

// P0.5 — the dedup node output only carries {intent_id, label}; the scheduler
// needs the runtime clientCode. Re-attach it from the resolved client scope.
const scope = $node['Resolve client'].json || {};
const out = Object.assign({}, $json || {});
out.clientCode = scope.clientCode || '';
return { json: out };
